-- Story-wide storyboard format + the per-shot sound prompt the cozy-ASMR
-- format generates. See history/story-formats.md.
--
-- format is unconstrained like motion_style_id: formats are code-defined
-- (lib/constants/story-formats.ts) and an unknown value resolves to
-- 'cinematic' in app code.
alter table stories
  add column format text not null default 'cinematic';

-- Null on every shot generated by a format that does not produce sound.
alter table shots
  add column sound_prompt text,
  add column sound_prompt_override text;
